// Tiny Cell service worker: precaches the whole game so it runs fully offline.
// Generated by tools/build_sw.py — edit tools/sw.template.js instead.
const VERSION = 'd3b932fde7';
const CACHE = 'tinycell-' + VERSION;
const ASSETS = [
  "./",
  "css/app.css",
  "css/style.css",
  "icons/apple-touch-icon.png",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/maskable-512.png",
  "index.html",
  "js/audio.js",
  "js/changelog.js",
  "js/game/abilities.js",
  "js/game/art.js",
  "js/game/bosses.js",
  "js/game/campaign.js",
  "js/game/cinematics.js",
  "js/game/creatures/t2.js",
  "js/game/creatures/t3.js",
  "js/game/creatures/t4.js",
  "js/game/creatures/t5.js",
  "js/game/data.js",
  "js/game/ecology.js",
  "js/game/game.js",
  "js/game/index.js",
  "js/game/style.js",
  "js/game/threats.js",
  "js/main.js",
  "js/rng.js",
  "js/store.js",
  "js/ui.js",
  "js/version.js",
  "manifest.webmanifest"
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(ASSETS.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('tinycell-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res && res.ok) cache.put(req, res.clone());
        return res;
      } catch (e) {
        // offline navigation fallback
        if (req.mode === 'navigate') {
          const shell = await cache.match('./index.html') || await cache.match('./');
          if (shell) return shell;
        }
        throw e;
      }
    })
  );
});
